Senda.Knowledge:Register({
  id = "warlock-rotation",
  class = "WARLOCK",
  kind = "rotation",
  title = "Rotación del brujo",
  levels = {1, 60},
  order = 100,
  status = "unverified",
  note = "Estragos: Blizzard dobló su coeficiente el 4-nov; el ajuste del 10-nov puede cambiarlo (citado sin enlace).",
  phase = {
    { from = 1, to = 3, spells = {686, 348}, text = "1. Descarga de las Sombras.\n2. Inmolar mientras viaja la descarga.\n3. Remata en cuerpo a cuerpo." },
    { from = 4, to = 7, spells = {172, 348, 5019}, text = "1. Corrupción.\n2. Inmolar.\n3. Varita hasta el final." },
    { from = 8, to = 9, spells = {980, 172, 5019}, text = "1. Terror de agonía.\n2. Corrupción.\n3. Varita." },
    { from = 10, to = 29, spells = {980, 172, 348, 5019, 689, 1120, 1454}, text = "1. Terror de agonía (desde 30 m).\n2. Corrupción.\n3. Envía al demonio.\n4. Inmolar.\n5. Varita, o Drenar vida si te falta vida.\n6. Drenar alma al enemigo casi muerto si te faltan Fragmentos de alma.\n\nTransfusión de vida al caminar." },
    { from = 30, to = 39, spells = {980, 172, 18265, 348, 689, 1454}, text = "1. Demonio al ataque.\n2. Terror de agonía + Corrupción (+ Succionar vida desde el 35).\n3. Inmolar solo si el enemigo va a durar.\n4. Drenar vida de relleno (drain tanking).\n5. Transfusión de vida cuando tu vida supere a tu maná.", note = "La fuente dice «Succionar vida desde el 35» aquí, pero la build de talentos lo coge al 36." },
    { from = 40, to = 60, spells = {172, 980, 18265, 686, 689, 1120, 348}, text = "**Aflicción:** Corrupción + Terror de agonía + Succionar vida siempre activos, y Estragos (Blizzard dobló su coeficiente el 4 nov; el ajuste del 10 nov puede cambiarlo). Descarga de las Sombras con Ocaso. Drenar vida de relleno. Drenar alma al final.\n\n**Destrucción:** Inmolar > Conflagrar > Incinerar de relleno. Eureka! con los cooldowns. Quemadura de las Sombras para rematar." },
  },
  hud = {
    { when = "Sin objetivo, fuera de combate, conoces Transfusión de vida, mana < 0.6 y hp > 0.7", suggest = "Transfusión de vida", spell = 1454 },
    { when = "hp < 0.35 y llevas Piedra de salud", suggest = "¡Piedra de salud!" },
    { when = "thp < 0.25, nivel >= 10, menos de 3 Fragmentos de alma y conoces Drenar alma", suggest = "Drenar alma", spell = 1120 },
    { when = "thp > 0.35 y al objetivo le falta tu Terror de agonía", suggest = "Terror de agonía", spell = 980 },
    { when = "thp > 0.2 y al objetivo le falta tu Corrupción", suggest = "Corrupción", spell = 172 },
    { when = "thp > 0.3 y al objetivo le falta tu Succionar vida", suggest = "Succionar vida", spell = 18265 },
    { when = "thp > 0.4 y al objetivo le falta tu Inmolar", suggest = "Inmolar", spell = 348 },
    { when = "hp < 0.6 y conoces Drenar vida", suggest = "Drenar vida", spell = 689 },
    { when = "mana < 0.2, hp > 0.5 y conoces Transfusión de vida", suggest = "Transfusión de vida", spell = 1454 },
    { when = "Llevas varita", suggest = "Varita", spell = 5019 },
    { when = "Siempre (último recurso)", suggest = "Descarga de las Sombras", spell = 686 },
  },
  warning = {
    { text = "Sin Piel/Armadura demoníaca", when = "No tienes ninguna aura de [ids].demon_armor_buffs (spells.toml)" },
    { text = "Sin demonio", when = "Nivel >= 2, conoces Invocar diablillo, no tienes demonio y no vas montado" },
    { text = "Sin Piedra de salud", when = "Nivel >= 10, conoces Crear piedra de salud y no llevas ninguna" },
    { text = "Pocos fragmentos", when = "Nivel >= 10 y menos de 2 Fragmentos de alma" },
    { text = "Talento(s) sin gastar", when = "Tienes puntos de talento sin gastar" },
    { text = "Bolsas llenas", when = "Menos de 3 huecos libres" },
  },
})

Senda.Knowledge:Register({
  id = "warlock-combat",
  class = "WARLOCK",
  kind = "page",
  title = "Combate en solitario",
  order = 110,
  status = "unverified",
  note = "La reducción de la probabilidad de fragmento por tick de Drenar alma es un cambio de Blizzard del 4-nov citado sin enlace.",
  block = {
    { heading = "El pull perfecto (solo)", body = "1. Demonio en pasivo. Marca el objetivo.\n2. Desde 30 m: Terror de agonía (macro SND_Abrir: envía al demonio a la vez).\n3. Corrupción (instantánea con el talento).\n4. Deja que el demonio golpee 1-2 segundos antes de Inmolar: Inmolar genera mucha amenaza de golpe.\n5. Varita hasta el final. Drenar vida si te falta vida. Drenar alma en el último 20% si necesitas fragmentos." },
    { heading = "Dos o tres enemigos", body = "- El demonio tanquea al primero. Tú pones Terror de agonía y Corrupción en el segundo y lo drenas.\n- Tercer enemigo: Miedo (el rango 1 dura 10 s y gasta menos maná). Cuando vuelva, otro Miedo.\n- Usa las macros _MO (mouseover) para poner DoTs sin cambiar de objetivo.\n- Con el Abisario: Tormento si un enemigo se le escapa." },
    { heading = "Gestión de maná y vida", body = "- Transfusión de vida cuando tu vida esté por encima de tu maná. Recupera la vida con Drenar vida.\n- Bebe solo cuando tengas poco de las dos cosas.\n- El Espíritu mejora Transfusión de vida en Forever.\n- Consumir sombras (Abisario) fuera de combate mientras haces Transfusión de vida." },
    { heading = "Emergencias, por orden", body = "1. Piedra de salud.\n2. Sacrificio del Abisario (escudo; no consume tiempo global).\n3. Miedo al enemigo que te pega.\n4. Espiral mortal (desde el 42): miedo de 3 s y cura.\n5. Aullido de terror (desde el 40) si son varios.\n6. Si vas a morir sin remedio: una Piedra de alma puesta en ti antes del combate te deja resucitar ahí mismo." },
    { heading = "Tipos de enemigo", body = "- **Lanzadores:** Maldición de la lengua o Bloqueo de hechizo del Manáfago. Pégate a ellos para que vengan al cuerpo a cuerpo.\n- **Los que huyen:** Maldición de temeridad (no huyen), o déjalos con DoTs y dispara con la varita.\n- **Guerreros y golpeadores fuertes:** Maldición de debilidad.\n- **Demonios y elementales élite:** Desterrar (desde el 28).\n- **Bestias:** el Íncubo o el Súcubo no pueden Seducir bestias; usa Miedo.\n- **Humanoides:** el Íncubo o el Súcubo pueden Seducir." },
    { heading = "Fragmentos de alma", body = "- Ten 3-5 siempre: Abisario, Íncubo o Manáfago (1 cada uno), Piedra de salud (1), Piedra de alma (1), Ritual de invocación (1).\n- Drenar alma: Blizzard redujo mucho la probabilidad de fragmento por tick. Lo seguro es que el enemigo muera mientras lo drenas.\n- La bolsa de almas va en la ranura de bolsa de componentes (la quinta): no te quita un hueco normal.\n- Las bolsas de almas (misiones del Íncubo y del Manáfago) los guardan aparte." },
    { heading = "Elección de demonio", body = "- **Abisario:** varios enemigos, élites, o cuando te falta equipo.\n- **Íncubo/Súcubo:** subir rápido contra un enemigo cada vez.\n- **Manáfago:** lanzadores y PvP.\n- **Diablillo:** grupos (Pacto de sangre)." },
  },
})

Senda.Knowledge:Register({
  id = "warlock-group",
  class = "WARLOCK",
  kind = "page",
  title = "Grupo, mazmorras y PvP",
  order = 120,
  status = "unverified",
  block = {
    { heading = "Antes del primer pull", body = "- Piedra de salud para cada miembro (créalas y dalas por comercio).\n- Piedra de alma en el sanador.\n- Ritual de invocación para traer a los que falten (en Forever es la única forma de invocar a una mazmorra).\n- Demonio: Diablillo (Pacto de sangre) casi siempre. Manáfago si hay muchos lanzadores. Abisario si no hay un buen tanque." },
    { heading = "Amenaza", body = "- No abras con Inmolar: espera 2-3 golpes del tanque.\n- DoTs en el objetivo marcado con calavera, varita, y Drenar vida si te falta vida.\n- Si se te viene un enemigo, Miedo solo si nadie lo va a tanquear: el miedo suelta enemigos por toda la sala.\n- Corrupción en varios objetivos genera amenaza repartida y puede quitarle enemigos al tanque. Pregunta antes." },
    { heading = "Utilidad que te van a pedir", body = "- Maldición de los elementos en jefes (en Forever cubre toda la magia; la de las Sombras ya no existe).\n- Maldición de temeridad en enemigos que huyen.\n- Desterrar demonios y elementales.\n- Subyugar demonio en zonas con demonios.\n- Drenar maná a lanzadores si tu grupo lo necesita.\n- Transfusión de vida: ojo, gasta tu vida y al sanador le cuesta maná. Recupérala con Drenar vida.", note = "«Maldición de los elementos cubre toda la magia y la de las Sombras ya no existe»: cambio de Forever sin fuente citada." },
    { heading = "PvP", body = "- **Demonio:** Manáfago (Bloqueo de hechizo, Devorar magia). Súcubo para Seducir.\n- **Gnomo:** Artista del escape te saca de raíces y ralentizaciones.\n- **Contra guerreros:** Miedo, Maldición de agotamiento (talento), corre y pon DoTs.\n- **Contra pícaros:** Armadura demoníaca siempre, Corrupción al primero que veas y Miedo nada más salir del sigilo.\n- **Contra magos:** Manáfago con Bloqueo de hechizo y Devorar magia para quitarle escudos.\n- **Contra sacerdotes:** Maldición de la lengua y Drenar maná.\n- **Contra cazadores:** pégate a ellos; su zona muerta de cerca les impide disparar.\n- **Contra paladines:** DoTs y aguanta; quitan maldiciones, así que prioriza Corrupción.\n- **Contra druidas:** Corrupción y Terror de agonía antes de que cambien de forma; Miedo cuando curen." },
  },
})

